def countWithFixedPoints(n, k):
    M = 1000000007
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % M
    m = n - k
    d0, d1 = 1, 0  # D(0), D(1)
    if m == 0:
        der = 1
    else:
        for i in range(2, m + 1):
            d0, d1 = d1, (i - 1) * (d0 + d1) % M
        der = d1
    comb = fact[n] * pow(fact[k] * fact[n - k] % M, M - 2, M) % M
    return comb * der % M
